-- Eco 15min circle data
DROP TABLE IF EXISTS public.eco_living_15min;
CREATE TABLE public.eco_living_15min (
    id SERIAL PRIMARY KEY,
    city text,
    district text,
    category text,
    name text,
    address text,
    longitude double precision,
    latitude double precision
);

SELECT pg_catalog.setval('public.eco_living_15min_id_seq', (SELECT COALESCE(MAX(id), 0) FROM public.eco_living_15min), true);